(async () => {
  if (!game.user?.isGM) return ui.notifications?.error("GM only.");
  const byName = new Map(PLAN.map(r => [r.name, r]));
  const TYPES = new Set(["gear", "equipment", "consumable", "weapon", "armor"]);
  const flagsFor = (r) => ({
    "flags.fourththing.rfi.item.tier": r.tier,
    "flags.fourththing.rfi.item.frame": r.frame,
    "flags.fourththing.rfi.item.price": {
      marks: r.marks, currency: r.currency, gmOverride: r.gmOverride, altCurrencies: {}, split: null,
      rarityMult: r.rarityMult, notes: r.notes, bound: r.bound, saleBack: r.saleBack
    }
  });
  const report = [];
  async function run(label, docs, apply) {
    const updates = [];
    for (const it of docs) {
      const r = byName.get(it.name); if (!r || !TYPES.has(String(it.type))) continue;
      if (it.flags?.fourththing?.rfi?.item?.tier) { report.push({ where: label, name: it.name, result: "skip (has tier)" }); continue; }
      updates.push({ _id: it.id, ...flagsFor(r) });
      report.push({ where: label, name: it.name, tier: r.tier, frame: r.frame, marks: r.marks, currency: r.currency, result: DRY_RUN ? "would stamp" : "stamped" });
    }
    if (updates.length && !DRY_RUN) await apply(updates);
    return updates.length;
  }
  let n = 0;
  const pack = game.packs.get(PACK_ID);
  if (!pack) ui.notifications?.warn(`Pack not found: ${PACK_ID}`);
  else {
    const docs = await pack.getDocuments();
    const wasLocked = pack.locked;
    n += await run(PACK_ID, docs, async (updates) => {
      if (wasLocked) await pack.configure({ locked: false });
      try { await Item.updateDocuments(updates, { pack: PACK_ID }); }
      finally { if (wasLocked) await pack.configure({ locked: true }); }
    });
  }
  if (INCLUDE_WORLD_ITEMS) n += await run("world", game.items.contents, (updates) => Item.updateDocuments(updates));
  console.table(report);
  ui.notifications?.info(`[untiered stamp] ${DRY_RUN ? "DRY RUN — would stamp" : "stamped"} ${n} item(s). See console.table.`);
})();
